// Vérification du quota quotidien LinkedIn
const today = new Date().toDateString();
const quotaKey = `linkedin_quota_${today}`;

// Récupérer le quota depuis les globals n8n (ou utiliser la DB)
let dailyCount = 0;
try {
  const stored = $execution.customData.get('linkedin_daily_count');
  const storedDate = $execution.customData.get('linkedin_quota_date');
  if (storedDate === today) {
    dailyCount = parseInt(stored || '0', 10);
  }
} catch (e) {}

const DAILY_LIMIT = 60;
const remaining = DAILY_LIMIT - dailyCount;

if (remaining <= 0) {
  throw new Error(`Quota LinkedIn journalier atteint (${DAILY_LIMIT}/jour). Reprise demain.`);
}

// Calcul du batch autorisé
const batchSize = Math.min(remaining, $input.all().length, 5);
const prospects = $input.all().slice(0, batchSize);

return prospects.map(item => ({
  json: {
    ...item.json,
    dailyCount,
    remaining,
    batchSize,
  }
}));

