const prospect = $('quota-check').item.json;
const claudeResponse = $input.item.json;
const message = claudeResponse.content[0].text.trim();

// Validation du message
if (!message || message.length > 300) {
  throw new Error(`Message invalide (longueur: ${message?.length})`);
}

// Délai aléatoire humain (45-90 secondes)
const delay = Math.floor(Math.random() * 45000) + 45000;

return [{
  json: {
    ...prospect,
    generatedMessage: message,
    actionDelay: delay,
    timestamp: new Date().toISOString(),
  }
}];
